- memory: Read and search your persistent memory log of board activities. Supports 'search' (returns matching entries with timestamps) and 'read' (returns a full entry by ID). parameters: {"type": "object", "properties": {"action": {"type": "string", "enum": ["search", "read"], "description": "The memory operation to perform"}, "query": {"type": "string", "description": "Search terms (for search) or entry ID (for read)"}}, "required": ["action", "query"]}
